(7039061, 1069649, 161988, '<td valign="top">Nice.</td>', 'Nice.', '2013-05-17 17:21:34.000000', NULL, 1),
(7039063, 1069589, 161988, '<td valign="top">Well done all the way around. Very pleasing photo to look at.</td>', 'Well done all the way around. Very pleasing photo to look at.', '2013-05-17 17:23:15.000000', NULL, 1),
(7039067, 1069567, 161988, '<td valign="top">I''m not sure the post processing here helped your photo but I get where you were trying to go. JMHO</td>', 'I''m not sure the post processing here helped your photo but I get where you were trying to go. JMHO', '2013-05-17 17:24:41.000000', NULL, 1),
(7039075, 1069477, 161988, '<td valign="top">Clever composition, the post processing works here !</td>', 'Clever composition, the post processing works here !', '2013-05-17 17:27:01.000000', NULL, 1),
(7039077, 1069750, 161988, '<td valign="top">Extraordinary concept and composition. Bravo!!!</td>', 'Extraordinary concept and composition. Bravo!!!', '2013-05-17 17:28:21.000000', NULL, 1),
(7039079, 1069748, 161988, '<td valign="top">Simplistically beautiful. Very nice water painting effect.</td>', 'Simplistically beautiful. Very nice water painting effect.', '2013-05-17 17:29:08.000000', NULL, 1),
