(7039081, 1069039, 161988, '<td valign="top">Hilarious.  I''m giving you a 9 based on the story telling aspect alone.</td>', 'Hilarious.  I''m giving you a 9 based on the story telling aspect alone.', '2013-05-17 17:33:44.000000', NULL, 1),
(7039082, 1069762, 161988, '<td valign="top">Some people are very brilliant and talented. It appears you''re one of them. Awesome, eye appealing work!</td>', 'Some people are very brilliant and talented. It appears you''re one of them. Awesome, eye appealing work!', '2013-05-17 17:34:44.000000', NULL, 1),
