(7039099, 1069711, 114225, '<td valign="top">Ok, I can see it. Wasn''t convinced this would make a good painting at first, but it does.</td>', 'Ok, I can see it. Wasn''t convinced this would make a good painting at first, but it does.', '2013-05-17 18:48:58.000000', NULL, 1),
(7039117, 1069685, 114225, '<td valign="top">A bit too smooth for me. Paintings have more texture to them.</td>', 'A bit too smooth for me. Paintings have more texture to them.', '2013-05-17 19:13:33.000000', NULL, 1),
(7039118, 1069198, 114225, '<td valign="top">Great scene to true into a painting. Although its a bit too smooth for my tastes. I want to see the texture the brushes create.</td>', 'Great scene to true into a painting. Although its a bit too smooth for my tastes. I want to see the texture the brushes create.', '2013-05-17 19:14:22.000000', NULL, 1),
(7039120, 1069653, 114225, '<td valign="top">Not sure I''ve seen many partial saturation paintings.<br/>I do like how this has the feeling of brush strokes.</td>', 'Not sure I''ve seen many partial saturation paintings.I do like how this has the feeling of brush strokes.', '2013-05-17 19:15:16.000000', NULL, 1),
