(7039626, 1069011, 114225, '<td valign="top">Wow, so much energy in this photo.</td>', 'Wow, so much energy in this photo.', '2013-05-18 20:46:40.000000', NULL, 1),
(7039627, 1069650, 114225, '<td valign="top">I''m not finding myself reading painting in this.</td>', 'I''m not finding myself reading painting in this.', '2013-05-18 20:47:00.000000', NULL, 1),
