(7039630, 1069589, 114225, '<td valign="top">Lovely scene. Too bad for that blown highlight, it cuts the image in half.</td>', 'Lovely scene. Too bad for that blown highlight, it cuts the image in half.', '2013-05-18 20:48:13.000000', NULL, 1),
(7039631, 1069640, 114225, '<td valign="top">A lot to try to take in here. It''s kind of messing with my mind.</td>', 'A lot to try to take in here. It''s kind of messing with my mind.', '2013-05-18 20:48:45.000000', NULL, 1),
