(7039634, 1069659, 114225, '<td valign="top">Hmmm, maybe it''s just me, but the yellow cast takes away from the rest of the processing.</td>', 'Hmmm, maybe it''s just me, but the yellow cast takes away from the rest of the processing.', '2013-05-18 20:49:44.000000', NULL, 1),
(7039635, 1069745, 114225, '<td valign="top">The canvas feel is nice. It works well with lines f the image.</td>', 'The canvas feel is nice. It works well with lines f the image.', '2013-05-18 20:50:35.000000', NULL, 1),
(7039640, 1069025, 114225, '<td valign="top">The processing is good for this, but I find the composition flat.</td>', 'The processing is good for this, but I find the composition flat.', '2013-05-18 20:58:45.000000', NULL, 1),
(7039641, 1069763, 114225, '<td valign="top">Nice colors. I find myself wishing for a different editing style on this. The canvas texture just doesn''t work as well on this as it does others.</td>', 'Nice colors. I find myself wishing for a different editing style on this. The canvas texture just doesn''t work as well on this as it does others.', '2013-05-18 20:59:42.000000', NULL, 1),
(7039642, 1069612, 114225, '<td valign="top">Nice brush strokes from the editing. Ht gives th a dynamic feel.</td>', 'Nice brush strokes from the editing. Ht gives th a dynamic feel.', '2013-05-18 21:00:09.000000', NULL, 1),
(7039643, 1069606, 114225, '<td valign="top">The open window really makes me like this a lot more than if the van were "perfect"</td>', 'The open window really makes me like this a lot more than if the van were "perfect"', '2013-05-18 21:00:39.000000', NULL, 1),
