(7039743, 1069256, 28427, '<td valign="top">While watching this, I was waiting.  Waiting to see Tintin enter the scene.  This is really how Hergé would have drawn it.</td>', 'While watching this, I was waiting.  Waiting to see Tintin enter the scene.  This is really how Hergé would have drawn it.', '2013-05-19 05:56:14.000000', NULL, 1),
(7039749, 1069648, 28427, '<td valign="top">I just love this :D The expression, the dandelion...Cool cow</td>', 'I just love this :D The expression, the dandelion...Cool cow', '2013-05-19 06:04:55.000000', NULL, 1),
(7039756, 1069039, 3306, '<td valign="top">Made me laugh!</td>', 'Made me laugh!', '2013-05-19 06:29:27.000000', NULL, 1),
(7039759, 1069702, 3306, '<td valign="top">There is only one person who could create such a magnificent work of art. Could I be wrong? Only if there is a twin imposter! Congratulations Christopher onyour blue ribbon!</td>', 'There is only one person who could create such a magnificent work of art. Could I be wrong? Only if there is a twin imposter! Congratulations Christopher onyour blue ribbon!', '2013-05-19 06:36:55.000000', NULL, 1),
(7039760, 1069762, 3306, '<td valign="top">Wonderful creativity. Polished technical ability. If you aren''t a professional, you should be. top 3.</td>', 'Wonderful creativity. Polished technical ability. If you aren''t a professional, you should be. top 3.', '2013-05-19 06:40:32.000000', NULL, 1),
(7039761, 1069477, 3306, '<td valign="top">What a wonderfully comical and creative characterization. One of my favorites!</td>', 'What a wonderfully comical and creative characterization. One of my favorites!', '2013-05-19 06:42:20.000000', NULL, 1),
(7039762, 1069310, 3306, '<td valign="top">Wow. It is apparent that you have put a lot of work into this rendition. Very creative and artistic.</td>', 'Wow. It is apparent that you have put a lot of work into this rendition. Very creative and artistic.', '2013-05-19 06:45:37.000000', NULL, 1),
(7039763, 1069490, 3306, '<td valign="top">Very well done. I love the personality emanating from this "painting".</td>', 'Very well done. I love the personality emanating from this "painting".', '2013-05-19 06:49:37.000000', NULL, 1),
(7039764, 1069648, 3306, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2013-05-19 06:51:03.000000', NULL, 1),
