(7039766, 1069230, 3306, '<td valign="top">I love Boston! Very nice work</td>', 'I love Boston! Very nice work', '2013-05-19 06:53:53.000000', NULL, 1),
(7039767, 1069606, 3306, '<td valign="top">You took an otherwise prosaic photo and made it an artistic masterpiece.</td>', 'You took an otherwise prosaic photo and made it an artistic masterpiece.', '2013-05-19 06:54:57.000000', NULL, 1),
(7039768, 1069590, 3306, '<td valign="top">The photograph is fantastic. I think you could have done more with the conversion to a painting style. This would have gotten a ribbon in any other challenge.</td>', 'The photograph is fantastic. I think you could have done more with the conversion to a painting style. This would have gotten a ribbon in any other challenge.', '2013-05-19 06:56:57.000000', NULL, 1),
(7039773, 1069750, 3306, '<td valign="top">You are one of my favorite artists on DP Challenge Samantha. Your creativity and technical ability is astounding. You have definitely found your purpose. There are so many wonderful pictures in this challenge. Yours is in the top 3.</td>', 'You are one of my favorite artists on DP Challenge Samantha. Your creativity and technical ability is astounding. You have definitely found your purpose. There are so many wonderful pictures in this challenge. Yours is in the top 3.', '2013-05-19 07:04:42.000000', NULL, 1),
(7039788, 1069617, 159200, '<td valign="top">This is so cool! Good work! Looks like something out of Tarzan!</td>', 'This is so cool! Good work! Looks like something out of Tarzan!', '2013-05-19 07:52:59.000000', NULL, 1),
(7039789, 1069739, 28427, '<td valign="top">Al the details you add in your work sometimes creeps me out.  Even without a title the spirit is clear through the dead people waiting in the abyss, Death approaching from the back, the burning buildings...<br/>All this in nearly one week; you''re a top artist Christophe.</td>', 'Al the details you add in your work sometimes creeps me out.  Even without a title the spirit is clear through the dead people waiting in the abyss, Death approaching from the back, the burning buildings...All this in nearly one week; you''re a top artist Christophe.', '2013-05-19 07:55:04.000000', NULL, 1),
(7039791, 1069256, 108580, '<td valign="top">This is the only image thus far that uses this Topaz Labs filter (<a href="//www.topazlabs.com/333.html" rel="nofollow" target="_blank">Simplify</a> - Oil Painting I think) It turned out really well, barring the 3D of the chandelier overlaying onto the wall painting. Were it not for that I''d have given it a 9.</td>', 'This is the only image thus far that uses this Topaz Labs filter (Simplify - Oil Painting I think) It turned out really well, barring the 3D of the chandelier overlaying onto the wall painting. Were it not for that I''d have given it a 9.', '2013-05-19 08:00:35.000000', NULL, 1),
(7039796, 1069687, 153814, '<td valign="top">This has a Grant Wood look to it (Man &amp; Woman with pitchfork).<br/>Great texture as well.<br/>I''m going to take a guess and say this is Chris (Mrchhas).<br/>Either way you did a great job on this. Well done.</td>', 'This has a Grant Wood look to it (Man & Woman with pitchfork).Great texture as well.I''m going to take a guess and say this is Chris (Mrchhas).Either way you did a great job on this. Well done.', '2013-05-19 09:04:24.000000', NULL, 1),
(7039829, 1069762, 28427, '<td valign="top">Very elegant.  Had to look twice at the legs, especially the pair on the left.  The filter gives this pair a \\\"special\\\" effect.  Luckily they''re clearly female legs and I realized soon enough that it was the filter and not a pair of hairy legs.  Sorry...don''t mean to offend you :) If it helps: your entry is one of the 3 I gave a 10.</td>', 'Very elegant.  Had to look twice at the legs, especially the pair on the left.  The filter gives this pair a \\\"special\\\" effect.  Luckily they''re clearly female legs and I realized soon enough that it was the filter and not a pair of hairy legs.  Sorry...don''t mean to offend you :) If it helps: your entry is one of the 3 I gave a 10.', '2013-05-19 11:07:43.000000', NULL, 1),
(7039830, 1069750, 28427, '<td valign="top">Nice pose of the model, beautiful clocks working perfectly in this photograph, a great combination of all elements finished with a perfect filter.</td>', 'Nice pose of the model, beautiful clocks working perfectly in this photograph, a great combination of all elements finished with a perfect filter.', '2013-05-19 11:09:28.000000', NULL, 1),
(7039844, 1068992, 28427, '<td valign="top">If you wouldn''t know this is a photograph, you would actually think it''s a photograph of a painting.  So: successful mission.</td>', 'If you wouldn''t know this is a photograph, you would actually think it''s a photograph of a painting.  So: successful mission.', '2013-05-19 11:59:49.000000', NULL, 1),
