(7041541, 1069589, 12611, '<td valign="top">Those odd blues and green in the background/treeline actually give the shot a great deal of depth when you stare at it for a while. Some nice detail, a very nicely "created" world you have.</td>', 'Those odd blues and green in the background/treeline actually give the shot a great deal of depth when you stare at it for a while. Some nice detail, a very nicely "created" world you have.', '2013-05-22 09:23:37.000000', NULL, 1),
(7041544, 1069659, 12611, '<td valign="top">Bryant Park it seems, the dapples of color are a fantastic painterly technique, and work wonders to un-focus the viewer, and allow the eyes to soar upward through the ethereal trees...</td>', 'Bryant Park it seems, the dapples of color are a fantastic painterly technique, and work wonders to un-focus the viewer, and allow the eyes to soar upward through the ethereal trees...', '2013-05-22 09:28:31.000000', NULL, 1),
(7041546, 1069610, 12611, '<td valign="top">One of my favorites here for sure. its a fantasy video game of shot, with far to real suggestions and implications.</td>', 'One of my favorites here for sure. its a fantasy video game of shot, with far to real suggestions and implications.', '2013-05-22 09:33:52.000000', NULL, 1),
