INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7042588, 1069702, 20799, '<td valign="top">"I have a few ideas", he said. You certainly did, congrats on the win!<br/>I was expecting a Caravaggio :-).</td>', '"I have a few ideas", he said. You certainly did, congrats on the win!I was expecting a Caravaggio :-).', '2013-05-24 03:31:14.000000', NULL, 0),
(7042589, 1069739, 108580, '<td valign="top">It is far more difficult commenting during voting than it is commenting post roll-over when hindsight and other comments make ones response an exact science. However it is also personally more rewarding and memorable, educational. I too battled with the desire to add a painterly processes, to which so many images were subjected to; canvas texture or PS filters for example. I however opted out as I preferred to show the photo-realistic ends painters go in their art. The exact opposite of what was implied in the challenges description.<br/>Your eloquence in describing your thoughts and processes of this particular work in such a way as to scoff at the reverse engineering of a composite to become a <strike>photo</strike> painting is ingenious. I found those traditional elements of paint in your entry, yet it wasn''t ALL like that and that is what confused me.<br/> <br/>Interestingly voters were more swayed toward/by oil, canvas and knives and it affected those images that were not splashes and strokes on anything but paper. Yours less than mine :/<br/><br/><i>Message edited by author 2013-05-24 02:40:22.</i></td>', 'It is far more difficult commenting during voting than it is commenting post roll-over when hindsight and other comments make ones response an exact science. However it is also personally more rewarding and memorable, educational. I too battled with the desire to add a painterly processes, to which so many images were subjected to; canvas texture or PS filters for example. I however opted out as I preferred to show the photo-realistic ends painters go in their art. The exact opposite of what was implied in the challenges description.Your eloquence in describing your thoughts and processes of this particular work in such a way as to scoff at the reverse engineering of a composite to become a photo painting is ingenious. I found those traditional elements of paint in your entry, yet it wasn''t ALL like that and that is what confused me. Interestingly voters were more swayed toward/by oil, canvas and knives and it affected those images that were not splashes and strokes on anything but paper. Yours less than mine :/', '2013-05-24 03:38:45.000000', '2013-05-24 03:40:22.000000', 0),
